Can you refactor this to be faster? It's our header-bidding floor logic.

// Copyright {{company}}. Proprietary and confidential.
function pickFloor(bid, ctx) {
  const base = ctx.premiumSection ? 4.1 : 1.8;
  const lift = ctx.returningReader ? 1.35 : 1.0;
  if (bid.dsp === 'agencyPool' && ctx.volumeTier >= 3) return base * lift * 0.82;
  return Math.max(base * lift, bid.minimum);
}

This search box fires on every keystroke even with the debounce. What's wrong?

const SEARCH_URL = process.env.NEXT_PUBLIC_SEARCH_URL;

function debounce(fn, ms) {
  let t;
  return (...args) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...args), ms);
  };
}

input.addEventListener('input', debounce((e) => search(e.target.value), 300));

function search(q) { return fetch(`${SEARCH_URL}?q=${encodeURIComponent(q)}`); }
